# Gather the requests that set this review off: each approval email as clean text, with the earlier mail of its thread.
import datetime
import json
from zoneinfo import ZoneInfo

from semoss import Insight

# Bounds that keep a long request and its thread inside the model's context.
MAX_TEXT = 12000
EARLIER = 3
EARLIER_TEXT = 1500


def _value(name, value):
    # Pixel decodes \u escapes, so mail text can never open an <encode> tag in the Pixel.
    return name + "=[" + json.dumps(value).replace("<", "\\u003c") + "]"


def _pixel(reactor, **args):
    ret = Insight().run_pixel(reactor + "(" + ", ".join(_value(k, v) for k, v in args.items()) + ");", raw=True)
    last = ret[0]["pixelReturn"][-1]
    if "ERROR" in str(last.get("operationType")):
        raise RuntimeError(reactor + " failed: " + str(last.get("output")))
    return last.get("output") or {}


def _prompt_data(value):
    # RunAgent URL-decodes a command holding "%", so escape it and "+" for the data to reach the model unchanged.
    return json.dumps(value, ensure_ascii=False).replace("%", "%25").replace("+", "%2B")


def _clip(text, size):
    text = str(text or "").strip()
    return text if len(text) <= size else text[:size].rstrip() + " [...]"


def _who(message):
    return message.get("fromName") or message.get("fromAddress")


def run(scope):
    thread_ids = list(scope.get("thread_ids") or [])
    message_keys = list(scope.get("message_keys") or [])
    requests = []
    for thread_id, key in zip(thread_ids, message_keys):
        messages = _pixel("BrainGetThreadMessages", threadId=thread_id, limit=20).get("messages") or []
        request = next((m for m in messages if m.get("emailRef") == "email:" + key), None)
        if request is None and messages:
            # the mailbox no longer shows that email, or a rule hides it; the newest message stands in
            request = messages[-1]
        if request is None:
            continue
        earlier = [m for m in messages if m is not request][-EARLIER:]
        requests.append({"n": len(requests) + 1, "messageId": request.get("id"), "subject": request.get("subject"),
                         "from": _who(request),
                         "fromAddress": request.get("fromAddress"), "at": request.get("at"),
                         "webLink": request.get("webLink"), "text": _clip(request.get("text"), MAX_TEXT),
                         "earlierInThread": [{"from": _who(m), "at": m.get("at"), "text": _clip(m.get("text"), EARLIER_TEXT)}
                                             for m in earlier]})
    if not requests:
        raise RuntimeError("None of the approval requests could be read from the mailbox.")
    try:
        zone = ZoneInfo(str(scope.get("timezone") or "UTC"))
    except Exception:
        zone = datetime.timezone.utc
    today = datetime.datetime.now(zone).strftime("%Y-%m-%d")
    # the Graph id is for deliver's draft reply only; a model that copies a long id can get it wrong
    review = [{k: v for k, v in r.items() if k != "messageId"} for r in requests]
    return {"today": today, "requests": requests,
            "reviewInput": _prompt_data({"today": today, "requests": review})}
